61	<script>
62	(function () {
63	  'use strict';
64	  var form = document.getElementById('draft-form');
65	  var titleInput = document.getElementById('title');
66	  var summaryInput = document.getElementById('summary');
67	  var bodyInput = document.getElementById('body');
68	  var saveBtn = document.getElementById('save-btn');
69	  var statusEl = document.getElementById('status');
70	  var listEl = document.getElementById('article-list');
71	  var emptyTip = document.getElementById('empty-tip');
72	  var articles = [];
73	  var saving = false;
74	
75	  function setStatus(text, kind) {
76	    statusEl.textContent = text || '';
77	    statusEl.className = 'status' + (kind ? ' ' + kind : '');
78	  }
79	  function setEmpty(text, kind) {
80	    emptyTip.textContent = text || '';
81	    emptyTip.className = 'empty' + (kind ? ' ' + kind : '');
82	    emptyTip.hidden = !text;
83	  }
84	  function formatTime(iso) {
85	    var d = new Date(iso);
86	    return isNaN(d.getTime()) ? String(iso) : d.toLocaleString();
87	  }
88	  function render() {
89	    var sorted = articles.slice().sort(function (a, b) {
90	      var ta = a && a.createdAt ? String(a.createdAt) : '';
91	      var tb = b && b.createdAt ? String(b.createdAt) : '';
92	      if (ta !== tb) return ta < tb ? 1 : -1;
93	      return 0;
94	    });
95	    listEl.textContent = '';
96	    sorted.forEach(function (article) {
97	      var card = document.createElement('article');
98	      card.className = 'draft';
99	      var h = document.createElement('h3');
100	      h.textContent = article.title == null ? '' : String(article.title);
101	      var meta = document.createElement('p');
102	      meta.className = 'meta';
103	      meta.textContent = '创建时间：' + formatTime(article.createdAt);
104	      var summary = document.createElement('p');
105	      summary.className = 'summary';
106	      summary.textContent = article.summary == null ? '' : String(article.summary);
107	      card.appendChild(h);
108	      card.appendChild(meta);
109	      card.appendChild(summary);
110	      var li = document.createElement('li');
111	      li.appendChild(card);
112	      listEl.appendChild(li);
113	    });
114	    setEmpty(sorted.length === 0 ? '还没有保存的草稿。' : '');
115	  }
116	  function load() {
117	    fetch('/api/articles', { headers: { accept: 'application/json' } })
118	      .then(function (r) {
119	        if (!r.ok) throw new Error('HTTP ' + r.status);
120	        return r.json();
121	      })
122	      .then(function (data) {
123	        articles = data && Array.isArray(data.articles) ? data.articles : [];
124	        render();
125	      })
126	      .catch(function (err) {
127	        articles = [];
128	        listEl.textContent = '';
129	        setEmpty('草稿列表加载失败：' + (err && err.message ? err.message : err), 'err');
130	      });
131	  }
132	
133	  function setSaving(on) {
134	    saving = on;
135	    saveBtn.disabled = on;
136	    saveBtn.textContent = on ? '保存中…' : '保存草稿';
137	  }
138	
139	  form.addEventListener('submit', function (event) {
140	    event.preventDefault();
141	    if (saving) return;
142	    var trimmedTitle = titleInput.value.trim();
143	    if (!trimmedTitle) {
144	      setStatus('标题不能为空。', 'err');
145	      titleInput.focus();
146	      return;
147	    }
148	    setSaving(true);
149	    setStatus('正在保存…', null);
150	    fetch('/api/articles', {
151	      method: 'POST',
152	      headers: { 'content-type': 'application/json', accept: 'application/json' },
153	      body: JSON.stringify({
154	        title: titleInput.value,
155	        summary: summaryInput.value,
156	        body: bodyInput.value
157	      })
158	    })
159	      .then(function (r) {
160	        return r.json().catch(function () { return null; }).then(function (data) {
161	          if (!r.ok || !data || !data.article) {
162	            throw new Error(data && data.error ? data.error : ('HTTP ' + r.status));
163	          }
164	          return data.article;
165	        });
166	      })
167	      .then(function (article) {
168	        articles.push(article);
169	        render();
170	        form.reset();
171	        setStatus('草稿已保存', 'ok');
172	        setSaving(false);
173	      })
174	      .catch(function (err) {
175	        setStatus('保存失败：' + (err && err.message ? err.message : err) + '，可修改后再次保存。', 'err');
176	        setSaving(false);
177	      });
178	  });
179	
180	  load();
181	})();
182	</script>
183	</html>`;
184	const args: string[] = process.argv.slice(2);
185	const help: string = `QuillPress - 内容编辑与刊物发布
186	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
187	       node server.ts --help
188	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
189	Port 0 selects an available port.
190	`;
191	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
192	  process.stdout.write(help);
193	  process.exit(args.length === 0 ? 2 : 0);
194	}
195	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
196	let host: string = '127.0.0.1';
197	let port: number = 8080;
198	let dataDir: string = 'data';
199	while (args.length) {
200	  const flag = args.shift();
201	  const value = args.shift();
202	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
203	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
204	  }
205	  if (flag === '--host') host = value;
206	  else if (flag === '--port') {
207	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
208	    port = Number(value);
209	  } else dataDir = value;
210	}
211	mkdirSync(dataDir, { recursive: true });
212	const dataFile = join(dataDir, 'articles.json');
213	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
214	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
215	}
216	
217	interface Article {
218	  id: string;
219	  title: string;
220	  summary: string;
221	  body: string;
222	  status: 'draft';
223	  createdAt: string;
224	}
225	interface DraftInput {
226	  title: string;
227	  summary: string;
228	  body: string;
229	}
230	
231	class HttpError extends Error {
232	  status: number;
233	  constructor(status: number, message: string) {
234	    super(message);
235	    this.name = 'HttpError';
236	    this.status = status;
237	  }
238	}
239	
240	function respond(res: ServerResponse, status: number, value: unknown, html = false): void {
241	  const body = html ? String(value) : JSON.stringify(value);
242	  res.writeHead(status, {
243	    'content-type': html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
244	    'content-length': Buffer.byteLength(body),
245	  });
246	  res.end(body);
247	}
248	
249	function methodNotAllowed(res: ServerResponse, allow: string): void {
250	  const body = JSON.stringify({ error: 'method not allowed' });
251	  res.writeHead(405, {
252	    'content-type': 'application/json; charset=utf-8',
253	    'content-length': Buffer.byteLength(body),
254	    allow,
255	  });
256	  res.end(body);
257	}
258	
259	function readArticles(): unknown[] {
260	  let parsed: unknown;
261	  try {
262	    parsed = JSON.parse(readFileSync(dataFile, 'utf8'));
263	  } catch (error) {
264	    throw new Error(`unable to read articles: ${(error as Error).message}`);
265	  }
266	  if (!Array.isArray(parsed)) throw new Error('unable to read articles: stored data is not a list');
267	  return parsed;
268	}
269	
270	// Serialize read-modify-write so concurrent saves never lose or corrupt records.
271	let writeQueue: Promise<void> = Promise.resolve();
272	function saveArticle(article: Article): Promise<void> {
273	  const run = writeQueue.then((): void => {
274	    const records = readArticles();
275	    records.push(article);
276	    const tmpFile = join(dataDir, `.articles.${process.pid}.tmp`);
277	    try {
278	      writeFileSync(tmpFile, `${JSON.stringify(records, null, 2)}\n`);
279	      renameSync(tmpFile, dataFile);
280	    } catch (error) {
281	      try { rmSync(tmpFile, { force: true }); } catch { /* best effort cleanup */ }
282	      throw new Error(`unable to save articles: ${(error as Error).message}`);
283	    }
284	  });
285	  writeQueue = run.then(() => undefined, () => undefined);
286	  return run;
287	}
288	
289	function readBody(req: IncomingMessage): Promise<string> {
290	  return new Promise((resolve, reject) => {
291	    const chunks: Buffer[] = [];
292	    let size = 0;
293	    let settled = false;
294	    req.on('data', (chunk: unknown) => {
295	      if (settled) return;
296	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
297	      size += buf.length;
298	      if (size > MAX_BODY_BYTES) {
299	        settled = true;
300	        reject(new HttpError(400, 'request body is too large'));
301	        req.destroy();
302	        return;
303	      }
304	      chunks.push(buf);
305	    });
306	    req.on('end', () => {
307	      if (!settled) resolve(Buffer.concat(chunks).toString('utf8'));
308	    });
309	    req.on('error', (error: Error) => {
310	      if (!settled) reject(new HttpError(400, `could not read request body: ${error.message}`));
311	    });
312	  });
313	}
314	
315	function validateDraftPayload(value: unknown): DraftInput {
316	  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
317	    throw new HttpError(400, 'request body must be a JSON object');
318	  }
319	  const data = value as Record<string, unknown>;
320	  if (typeof data.title !== 'string') {
321	    throw new HttpError(400, 'title must be a string');
322	  }
323	  const title = data.title.trim();
324	  if (title.length === 0) {
325	    throw new HttpError(400, 'title must not be empty or only whitespace');
326	  }
327	  let summary = '';
328	  if (Object.prototype.hasOwnProperty.call(data, 'summary')) {
329	    if (typeof data.summary !== 'string') throw new HttpError(400, 'summary must be a string when provided');
330	    summary = data.summary;
331	  }
332	  if (typeof data.body !== 'string') {
333	    throw new HttpError(400, 'body must be a string');
334	  }
335	  return { title, summary, body: data.body };
336	}
337	
338	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
339	  let route: string;
340	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; }
341	  catch { respond(res, 400, { error: 'invalid request path' }); return; }
342	
343	  if (!['/', '/health', '/api/articles'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
344	
345	  if (route === '/') {
346	    if (req.method === 'GET') { respond(res, 200, PAGE, true); return; }
347	    methodNotAllowed(res, 'GET');
348	    return;
349	  }
350	  if (route === '/health') {
351	    if (req.method === 'GET') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
352	    methodNotAllowed(res, 'GET');
353	    return;
354	  }
355	
356	  if (req.method === 'GET') {
357	    respond(res, 200, { [RESOURCE]: readArticles() });
358	    return;
359	  }
360	  if (req.method === 'POST') {
361	    const text = await readBody(req);
362	    let payload: unknown;
363	    try {
364	      payload = JSON.parse(text);
365	    } catch (error) {
366	      throw new HttpError(400, `invalid JSON: ${(error as Error).message}`);
367	    }
368	    const fields = validateDraftPayload(payload);
369	    const article: Article = {
370	      id: randomUUID(),
371	      title: fields.title,
372	      summary: fields.summary,
373	      body: fields.body,
374	      status: 'draft',
375	      createdAt: new Date().toISOString(),
376	    };
377	    await saveArticle(article);
378	    respond(res, 201, { article });
379	    return;
380	  }
381	  methodNotAllowed(res, 'GET, POST');
382	}
383	
384	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
385	  handle(req, res).catch((error: unknown) => {
386	    if (res.writableEnded) return;
387	    if (error instanceof HttpError) {
388	      respond(res, error.status, { error: error.message });
389	      return;
390	    }
391	    respond(res, 500, { error: error instanceof Error ? error.message : 'internal error' });
392	  });
393	});
394	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
395	server.listen(port, host, (): void => {
396	  const address = server.address();
397	  if (address && typeof address !== 'string') {
398	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
399	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
400	  }
401	});
402	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
403	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
404	}
